"use client";

import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { RefreshIcon } from "@/components/blocks/parts/icons";
import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";

import { seededRandom } from "../lib/plot";
import { BlockFrame } from "../parts/block-frame";
import { LEADS, type LeadFactors, scoreOf } from "./lead-scoring/data";
import { LeadRow } from "./lead-scoring/lead-row";

type Sort = "score" | "newest";

const SORTS: { value: Sort; label: string }[] = [
  { value: "score", label: "Score" },
  { value: "newest", label: "Newest" },
];

const clamp = (value: number) => Math.max(5, Math.min(99, Math.round(value)));

/** Nudges every factor a little, as a fresh read of the leads' activity would. The same round always gives the same result. */
function rescore(round: number): LeadFactors[] {
  if (round === 0) return LEADS.map((lead) => lead.factors);
  const random = seededRandom(round * 97 + 13);
  return LEADS.map(({ factors }) => ({
    fit: clamp(factors.fit + (random() - 0.5) * 6),
    intent: clamp(factors.intent + (random() - 0.5) * 30),
    engagement: clamp(factors.engagement + (random() - 0.5) * 26),
    timing: clamp(factors.timing + (random() - 0.5) * 14),
  }));
}

/**
 * Inbound leads ranked by fit. Each row shows who, why and a score ring; an
 * open row adds the signals, four factor bars and a push to the sales tool.
 * Re-sorting or rescoring glides the rows to their new places.
 */
export function LeadScoring({ className }: { className?: string }) {
  const [sort, setSort] = useState<Sort>("score");
  const [round, setRound] = useState(0);
  const [scoring, setScoring] = useState(false);
  const [openId, setOpenId] = useState<string | null>(LEADS[0]!.id);
  const titleId = useId();
  const rowId = useId();
  const headers = useRef(new Map<string, HTMLButtonElement>());

  useEffect(() => {
    if (!scoring) return;
    const id = window.setTimeout(() => {
      setRound((current) => current + 1);
      setScoring(false);
    }, 900);
    return () => window.clearTimeout(id);
  }, [scoring]);

  const factors = rescore(round);
  const rows = LEADS.map((lead, index) => ({
    lead,
    index,
    factors: factors[index] ?? lead.factors,
    score: scoreOf(factors[index] ?? lead.factors),
  }));
  rows.sort((a, b) =>
    sort === "score"
      ? b.score - a.score
      : a.lead.minutesAgo - b.lead.minutesAgo,
  );
  const hot = rows.filter((row) => row.score >= 75).length;

  const onKeyDown =
    (position: number) => (event: KeyboardEvent<HTMLButtonElement>) => {
      let next: number;
      if (event.key === "ArrowDown")
        next = Math.min(rows.length - 1, position + 1);
      else if (event.key === "ArrowUp") next = Math.max(0, position - 1);
      else if (event.key === "Home") next = 0;
      else if (event.key === "End") next = rows.length - 1;
      else return;
      event.preventDefault();
      const id = rows[next]?.lead.id;
      if (id) headers.current.get(id)?.focus();
    };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Inbound leads
          </h2>
          <p role="status" className="text-sm text-muted-foreground">
            {scoring
              ? `Rescoring ${LEADS.length} leads`
              : `${LEADS.length} new this week, ${hot} strong fits`}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <SegmentedControl
            aria-label="Sort leads by"
            options={SORTS}
            value={sort}
            onValueChange={setSort}
          />
          <Button
            variant="outline"
            size="sm"
            onClick={() => setScoring(true)}
            disabled={scoring}
          >
            <RefreshIcon
              aria-hidden="true"
              className={scoring ? "size-4 motion-safe:animate-spin" : "size-4"}
            />
            {scoring ? "Rescoring" : "Rescore"}
          </Button>
        </div>
      </header>
      <ol aria-busy={scoring} className="flex flex-col">
        {rows.map((row, position) => (
          <LeadRow
            key={row.lead.id}
            lead={row.lead}
            factors={row.factors}
            score={row.score}
            tint={row.index}
            open={openId === row.lead.id}
            onToggle={() =>
              setOpenId(openId === row.lead.id ? null : row.lead.id)
            }
            onKeyDown={onKeyDown(position)}
            headerRef={(node) => {
              if (node) headers.current.set(row.lead.id, node);
              else headers.current.delete(row.lead.id);
            }}
            panelId={`${rowId}-${row.lead.id}`}
          />
        ))}
      </ol>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

