/** The overall score: fit and intent count most. */
export function scoreOf(factors: LeadFactors): number {
  return Math.round(
    factors.fit * 0.3 +
      factors.intent * 0.3 +
      factors.engagement * 0.2 +
      factors.timing * 0.2,
  );
}

/** A short time since the lead came in, such as 12 min or 1 day. */
export function formatAgo(minutes: number): string {
  if (minutes < 60) return `${minutes} min`;
  if (minutes < 1440) return `${Math.round(minutes / 60)} h`;
  const days = Math.round(minutes / 1440);
  return `${days} ${days === 1 ? "day" : "days"}`;
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import type { KeyboardEvent, Ref } from "react";

import { ChevronDownIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { Initials } from "../parts/initials";
import { CrmPush } from "./crm-push";
import { FACTORS, type Lead, type LeadFactors, formatAgo } from "./data";
import { ScoreRing } from "./score-ring";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/** Props for one lead in the ranked list. */
export interface LeadRowProps {
  lead: Lead;
  factors: LeadFactors;
  score: number;
  /** Its place in the original list, which keeps the person's tint. */
  tint: number;
  open: boolean;
  onToggle: () => void;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  headerRef: Ref<HTMLButtonElement>;
  panelId: string;
}

// Critically damped: the row opens to its measured height and stops without a bounce.
const OPEN: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 41,
  mass: 1,
};
const GLIDE: Transition = {
  type: "spring",
  stiffness: 380,
  damping: 39,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/**
 * One lead: a header button with the person, the reason, the time and the
 * score ring, and a panel that springs open with signals, the four factor
 * bars and the push to the sales tool. Re-sorting glides the row to its new place.
 */
export function LeadRow({
  lead,
  factors,
  score,
  tint,
  open,
  onToggle,
  onKeyDown,
  headerRef,
  panelId,
}: LeadRowProps) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.li
      layout={reduceMotion ? false : "position"}
      transition={GLIDE}
      className="border-b border-border last:border-b-0"
    >
      <h3>
        <Button
          ref={headerRef}
          variant="ghost"
          aria-expanded={open}
          aria-controls={panelId}
          onClick={onToggle}
          onKeyDown={onKeyDown}
          size="sm"
          className="w-full justify-start text-left whitespace-normal"
        >
          <span className="flex w-full items-center gap-3 px-5 py-3 font-normal">
            <Initials name={lead.name} tint={tint} className="size-8" />
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="flex min-w-0 items-baseline gap-2">
                <span className="truncate text-sm font-semibold">
                  {lead.name}
                </span>
                <span className="hidden truncate text-xs text-muted-foreground @md:inline">
                  {lead.role}, {lead.company}
                </span>
              </span>
              <span className="truncate text-xs text-muted-foreground @md:hidden">
                {lead.role}, {lead.company}
              </span>
              <span className="line-clamp-1 text-sm text-muted-foreground">
                {lead.reason}
              </span>
            </span>
            <span className="hidden text-xs whitespace-nowrap text-muted-foreground tabular-nums @sm:inline">
              {formatAgo(lead.minutesAgo)}
            </span>
            <ScoreRing score={score} />
            <span className="sr-only">Score {score} out of 100.</span>
            <ChevronDownIcon
              aria-hidden="true"
              className={cn(
                "size-4 shrink-0 text-muted-foreground motion-safe:transition-transform",
                open ? "rotate-180" : undefined,
              )}
            />
          </span>
        </Button>
      </h3>
      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            id={panelId}
            role="region"
            aria-label={`${lead.name} details`}
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={reduceMotion ? INSTANT : OPEN}
            className="overflow-hidden"
          >
            <div className="flex flex-col gap-4 px-5 pt-1 pb-4 @md:pl-16">
              <ul aria-label="Signals" className="flex flex-wrap gap-1.5">
                {lead.signals.map((signal) => (
                  <li
                    key={signal}
                    className="rounded-full border border-border px-2.5 py-0.5 text-xs"
                  >
                    {signal}
                  </li>
                ))}
              </ul>
              <dl className="grid gap-x-6 gap-y-2.5 @md:grid-cols-2">
                {FACTORS.map((factor) => (
                  <div
                    key={factor.key}
                    className="grid grid-cols-[1fr_auto] gap-y-1 text-xs"
                  >
                    <dt className="text-muted-foreground">{factor.label}</dt>
                    <dd className="text-right font-medium tabular-nums">
                      {factors[factor.key]}
                    </dd>
                    <dd
                      aria-hidden="true"
                      className="col-span-2 h-1.5 overflow-hidden rounded-full bg-muted"
                    >
                      <span
                        className={cn(
                          "block h-full w-(--w) rounded-full motion-safe:transition-all motion-safe:duration-500",
                          factor.bar,
                        )}
                        style={
                          // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
                          { "--w": `${factors[factor.key]}%` } as VarStyle
                        }
                      />
                    </dd>
                  </div>
                ))}
              </dl>
              <CrmPush name={lead.name} />
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </motion.li>
  );
}

import { cn } from "@/lib/utils";

/** The tinted surface and ink pairs a person's initials can sit on. Each pair passes contrast in both themes. */
const TINTS = [
  "bg-marketing-blue-surface text-marketing-blue-ink",
  "bg-marketing-green-surface text-marketing-green-ink",
  "bg-marketing-orange-surface text-marketing-orange-ink",
