/** Props for the push to the sales tool. */
export interface CrmPushProps {
  /** The lead's name, for the button's spoken label. */
  name: string;
}

const STEPS = 20;

/** Sends a lead to the sales tool, with a progress bar while it goes and a receipt when it lands. */
export function CrmPush({ name }: CrmPushProps) {
  const send = useTicker(STEPS, 55);
  const sending = send.running;
  const sent = send.done;

  return (
    <div className="flex flex-wrap items-center gap-3">
      <Button
        size="sm"
        onClick={send.start}
        disabled={sending || sent}
        aria-label={
          sent ? `${name} sent to Pipeway` : `Send ${name} to Pipeway`
        }
      >
        {sent ? (
          <CheckIcon aria-hidden="true" className="size-4" />
        ) : (
          <ShareIcon aria-hidden="true" className="size-4" />
        )}
        {sent ? "Sent to Pipeway" : sending ? "Sending" : "Send to Pipeway"}
      </Button>
      {sending ? (
        <span
          role="progressbar"
          aria-label="Sending"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round((send.tick / STEPS) * 100)}
          className="h-1.5 w-24 overflow-hidden rounded-full bg-muted"
        >
          <span
            className="block h-full w-(--w) rounded-full bg-chart-1"
            style={
              // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
              { "--w": `${(send.tick / STEPS) * 100}%` } as VarStyle
            }
          />
        </span>
      ) : null}
      <span role="status" className="text-xs text-muted-foreground">
        {sent ? "Deal created in the New leads stage" : ""}
      </span>
    </div>
  );
}

