export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

"use client";

import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react";
import { useEffect } from "react";

import { cn } from "@/lib/utils";

/** Props for a score ring. */
export interface ScoreRingProps {
  /** The score, from 0 to 100. */
  score: number;
  className?: string;
}

const RADIUS = 15;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

/** The hue of a ring by score band: strong, middling, weak. */
function ringHue(score: number) {
  if (score >= 75) return "stroke-chart-2";
  if (score >= 50) return "stroke-chart-1";
  return "stroke-chart-3";
}

/**
 * A ring whose arc and number share one animated value, so they count up
 * together. With reduced motion the value jumps. Decorative: the row says
 * the score in words.
 */
export function ScoreRing({ score, className }: ScoreRingProps) {
  const reduceMotion = useReducedMotion();
  const value = useMotionValue(0);
  const offset = useTransform(
    value,
    (current) => CIRCUMFERENCE * (1 - current / 100),
  );
  const label = useTransform(value, (current) => String(Math.round(current)));

  useEffect(() => {
    const controls = animate(
      value,
      score,
      reduceMotion
        ? { duration: 0 }
        : { duration: 0.7, ease: [0.165, 0.84, 0.44, 1] },
    );
    return () => controls.stop();
  }, [score, reduceMotion, value]);

  return (
    <span
      aria-hidden="true"
      className={cn(
        "relative inline-flex size-10 shrink-0 items-center justify-center",
        className,
      )}
    >
      <svg
        viewBox="0 0 36 36"
        className="absolute inset-0 size-full -rotate-90"
      >
        <circle
          cx="18"
          cy="18"
          r={RADIUS}
          fill="none"
          strokeWidth="3"
          className="stroke-muted"
        />
        <motion.circle
          cx="18"
          cy="18"
          r={RADIUS}
          fill="none"
          strokeWidth="3"
          strokeLinecap="round"
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={offset}
          className={cn(
            ringHue(score),
            "motion-safe:transition-all motion-safe:duration-300",
          )}
        />
      </svg>
      <motion.span className="text-xs font-semibold tabular-nums">
        {label}
      </motion.span>
    </span>
  );
}
